/**
 * 面板派生统计：按时间范围聚合、高峰时段推断、Token 构成拆分。
 *
 * 这些计算同时被总览卡片与活跃度热力图使用，集中在此以保证两者口径一致。
 */

import type { MetricsSnapshot, TokenCounters, TokenCountersWithRate } from '../shared/types'
import { cacheHitRate, costOf, emptyCounters, mergeCounters, resolveModelKey } from '../shared/utils'
import { dayKey } from '../shared/utils'

export type TimeRange = 'today' | '24h' | '3d' | '7d' | '30d' | 'all'

/** 时间范围全集，顺序即界面上的排列顺序；也是持久化时的合法值白名单。 */
export const TIME_RANGES: readonly TimeRange[] = ['today', '24h', '3d', '7d', '30d', 'all']

const DAY_MS = 86_400_000
const HOUR_MS = 3_600_000
/** 「全部」范围下热力图至少铺满的周长，避免数据稀疏时网格塌缩成一列。 */
const MIN_ALL_SPAN_DAYS = 168

export interface RangeStats {
  totalTokens: number
  calls: number
  activeDays: number
  sessionCount: number
  cacheHitRate: number
  inputTokens: number
  outputTokens: number
  cacheReadTokens: number
  cacheWriteTokens: number
  reasoningTokens: number
}

export interface CompositionPart {
  key: 'input' | 'output' | 'cacheRead' | 'cacheWrite'
  value: number
}

/** 各范围覆盖的自然日数量；'24h' 与 'all' 由调用方另行处理。 */
const RANGE_DAYS: Record<Exclude<TimeRange, 'all' | '24h'>, number> = {
  today: 1,
  '3d': 3,
  '7d': 7,
  '30d': 30,
}

/** 热力图固定展示最近 12 个自然月，与时间范围选择无关（GitHub 贡献图口径）。 */
export const HEATMAP_MONTHS = 12

/**
 * 热力图的日期序列：起点回溯 12 个月并对其所在周的周一，终点补齐到本周周日，
 * 使每一列都是完整自然周（周一为首日），未来日期由调用方标记为空白。
 */
export function heatmapDays(now = Date.now()): string[] {
  const anchor = new Date(now)
  anchor.setHours(0, 0, 0, 0)
  const start = new Date(anchor)
  start.setMonth(start.getMonth() - HEATMAP_MONTHS)
  // getDay() 以周日为 0，换算成周一为 0 的偏移
  const leading = (start.getDay() + 6) % 7
  const trailing = 6 - ((anchor.getDay() + 6) % 7)
  const startMs = start.getTime() - leading * DAY_MS
  const endMs = anchor.getTime() + trailing * DAY_MS

  // 用日历加一天而不是固定毫秒数，避免夏令时切换当天被跳过或重复
  const days: string[] = []
  const cursor = new Date(startMs)
  while (cursor.getTime() <= endMs) {
    days.push(dayKey(cursor))
    cursor.setDate(cursor.getDate() + 1)
  }
  return days
}

/** 生成覆盖该范围的日期序列（升序，最后一项为今天）。 */
export function rangeDayKeys(snapshot: MetricsSnapshot, range: TimeRange, now = Date.now()): string[] {
  const today = dayKey(now)
  if (range === '24h') {
    // 滚动窗口可能横跨两天，按自然日展开后再由区间过滤兜底
    return [dayKey(now - DAY_MS), today]
  }
  if (range !== 'all') {
    const span = RANGE_DAYS[range]
    return Array.from({ length: span }, (_, i) => dayKey(now - (span - 1 - i) * DAY_MS))
  }

  const known = Object.keys(snapshot.byDay).sort()
  const earliest = known[0] ?? today
  const elapsed = Math.ceil((now - new Date(`${earliest}T00:00:00`).getTime()) / DAY_MS)
  const span = Math.max(MIN_ALL_SPAN_DAYS, Number.isFinite(elapsed) ? elapsed : MIN_ALL_SPAN_DAYS)
  return Array.from({ length: span }, (_, i) => dayKey(now - (span - 1 - i) * DAY_MS))
}

/** 按范围汇总；「全部」直接取已算好的全局总计，避免重复累加。 */
export function computeRangeStats(
  snapshot: MetricsSnapshot,
  range: TimeRange,
  now = Date.now(),
): RangeStats {
  if (range === 'all') {
    const all = snapshot.totals.all
    return {
      totalTokens: all.totalTokens,
      calls: all.calls,
      activeDays: Object.values(snapshot.byDay).filter(day => (day.totalTokens ?? 0) > 0).length,
      sessionCount: snapshot.sessionCount,
      cacheHitRate: all.cacheHitRate,
      inputTokens: all.inputTokens,
      outputTokens: all.outputTokens,
      cacheReadTokens: all.cacheReadTokens,
      cacheWriteTokens: all.cacheWriteTokens,
      reasoningTokens: all.reasoningTokens,
    }
  }

  if (range === '24h') {
    const acc24 = emptyCounters()
    const windowStart = Math.floor((now - 24 * HOUR_MS) / HOUR_MS)
    const activeDayKeys = new Set<string>()
    for (const bucket of snapshot.recentHours) {
      if (bucket.hour < windowStart) continue
      mergeCounters(acc24, bucket.counters)
      if ((bucket.counters.totalTokens ?? 0) > 0) {
        activeDayKeys.add(dayKey(bucket.hour * HOUR_MS))
      }
    }
    const sessionCutoff = now - 24 * HOUR_MS
    let sessionCount24 = 0
    for (const session of Object.values(snapshot.bySession)) {
      if ((session.lastAt ?? 0) >= sessionCutoff || (session.firstAt ?? 0) >= sessionCutoff) sessionCount24 += 1
    }
    return {
      totalTokens: acc24.totalTokens,
      calls: acc24.calls,
      activeDays: activeDayKeys.size,
      sessionCount: sessionCount24,
      cacheHitRate: cacheHitRate(acc24),
      inputTokens: acc24.inputTokens,
      outputTokens: acc24.outputTokens,
      cacheReadTokens: acc24.cacheReadTokens,
      cacheWriteTokens: acc24.cacheWriteTokens,
      reasoningTokens: acc24.reasoningTokens,
    }
  }

  const acc = emptyCounters()
  let activeDays = 0
  for (const day of rangeDayKeys(snapshot, range, now)) {
    const counters = snapshot.byDay[day]
    if (!counters) continue
    mergeCounters(acc, counters)
    if ((counters.totalTokens ?? 0) > 0) activeDays += 1
  }

  const cutoff = range === 'today'
    ? new Date(`${dayKey(now)}T00:00:00`).getTime()
    : now - RANGE_DAYS[range] * DAY_MS
  let sessionCount = 0
  for (const session of Object.values(snapshot.bySession)) {
    if ((session.lastAt ?? 0) >= cutoff || (session.firstAt ?? 0) >= cutoff) {
      sessionCount += 1
    }
  }

  return {
    totalTokens: acc.totalTokens,
    calls: acc.calls,
    activeDays,
    sessionCount,
    cacheHitRate: cacheHitRate(acc),
    inputTokens: acc.inputTokens,
    outputTokens: acc.outputTokens,
    cacheReadTokens: acc.cacheReadTokens,
    cacheWriteTokens: acc.cacheWriteTokens,
    reasoningTokens: acc.reasoningTokens,
  }
}

/**
 * 推断调用最密集的小时。
 *
 * 优先使用小时级分布；历史账本没有该字段时，退回按会话时间戳加权推断。
 */
export function peakHour(snapshot: MetricsSnapshot): number | null {
  let best: number | null = null
  let bestCalls = 0

  for (const [rawHour, counters] of Object.entries(snapshot.byHour ?? {})) {
    const hour = Number(rawHour)
    if (!Number.isInteger(hour) || hour < 0 || hour > 23) continue
    const calls = counters.calls ?? 0
    if (calls > bestCalls) {
      bestCalls = calls
      best = hour
    }
  }
  if (best !== null) return best

  const bySessionHour = new Map<number, number>()
  for (const session of Object.values(snapshot.bySession)) {
    const at = session.lastAt || session.firstAt
    if (!at) continue
    const hour = new Date(at).getHours()
    bySessionHour.set(hour, (bySessionHour.get(hour) ?? 0) + (session.counters?.calls ?? 1))
  }
  for (const [hour, calls] of bySessionHour) {
    if (calls > bestCalls) {
      bestCalls = calls
      best = hour
    }
  }
  return best
}

/** 24 小时制显示，避免依赖具体语言的分时段措辞。 */
export function formatHour(hour: number): string {
  return `${String(hour).padStart(2, '0')}:00`
}

/** Token 构成：四项之和即 totalTokens（totalTokens 由上游缺失时按此四项求和得出）。 */
export function compositionParts(stats: RangeStats): CompositionPart[] {
  return [
    { key: 'input', value: stats.inputTokens },
    { key: 'output', value: stats.outputTokens },
    { key: 'cacheRead', value: stats.cacheReadTokens },
    { key: 'cacheWrite', value: stats.cacheWriteTokens },
  ]
}

export interface RhythmStats {
  /** 活跃日均用量；无活跃日时为 0。 */
  avgPerActiveDay: number
  peakDay: { day: string; tokens: number } | null
  /** 最长连续活跃天数。 */
  longestStreak: number
}

/** 使用节奏洞察：补充热力图之外的聚合结论，避免卡片右侧留白。 */
export function computeRhythm(snapshot: MetricsSnapshot, days: string[]): RhythmStats {
  let activeDays = 0
  let total = 0
  let peakDay: RhythmStats['peakDay'] = null
  let longestStreak = 0
  let currentStreak = 0

  for (const day of days) {
    const tokens = snapshot.byDay[day]?.totalTokens ?? 0
    if (tokens > 0) {
      activeDays += 1
      total += tokens
      currentStreak += 1
      if (currentStreak > longestStreak) longestStreak = currentStreak
      if (peakDay === null || tokens > peakDay.tokens) peakDay = { day, tokens }
    } else {
      currentStreak = 0
    }
  }

  return {
    avgPerActiveDay: activeDays > 0 ? Math.round(total / activeDays) : 0,
    peakDay,
    longestStreak,
  }
}

export type RelativeUnit = 'now' | 'minute' | 'hour' | 'day'

export interface RelativeTime {
  unit: RelativeUnit
  count: number
}

/** 把时间戳折算成「刚刚 / N 分钟前 / N 小时前 / N 天前」，用于会话榜单的活跃时间。 */
export function relativeTime(timestamp: number | undefined, now = Date.now()): RelativeTime | null {
  if (!timestamp || !Number.isFinite(timestamp)) return null
  const diff = now - timestamp
  if (diff < 0) return { unit: 'now', count: 0 }
  const minutes = Math.floor(diff / 60_000)
  if (minutes < 1) return { unit: 'now', count: 0 }
  if (minutes < 60) return { unit: 'minute', count: minutes }
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return { unit: 'hour', count: hours }
  return { unit: 'day', count: Math.floor(hours / 24) }
}

export interface CostSummary {
  total: number
  /** 没有任何模型能匹配到价格时为 true，UI 据此隐藏金额。 */
  unavailable: boolean
  /** 有用量但缺价格的模型名。 */
  missing: string[]
}

/** 区间成本：按模型各自的单价累加，缺价模型单独报出而不是按 0 计算。 */
export function computeRangeCost(snapshot: MetricsSnapshot, days: string[]): CostSummary {
  const inRange = new Set(days)
  let total = 0
  let priced = false
  const missing: string[] = []

  for (const [model, dayMap] of Object.entries(snapshot.byModelDay ?? {})) {
    const priceKey = resolveModelKey(snapshot.pricing, model)
    const price = priceKey ? snapshot.pricing[priceKey] : undefined
    let tokens = 0
    let cost = 0
    for (const [day, counters] of Object.entries(dayMap)) {
      if (!inRange.has(day)) continue
      tokens += counters.totalTokens ?? 0
      if (price) cost += costOf(counters, price)
    }
    if (tokens <= 0) continue
    if (!price) {
      missing.push(model)
      continue
    }
    priced = true
    total += cost
  }

  return { total, unavailable: !priced, missing }
}

/** 逐日成本，用于成本迷你趋势线。 */
export function dailyCostSeries(snapshot: MetricsSnapshot, days: string[]): number[] {
  return days.map(day => {
    let cost = 0
    for (const [model, dayMap] of Object.entries(snapshot.byModelDay ?? {})) {
      const priceKey = resolveModelKey(snapshot.pricing, model)
    const price = priceKey ? snapshot.pricing[priceKey] : undefined
      const counters = dayMap[day]
      if (!price || !counters) continue
      cost += costOf(counters, price)
    }
    return cost
  })
}

/** 滚动 24 小时窗口内的小时桶。 */
function windowedHours(snapshot: MetricsSnapshot, now = Date.now()) {
  const windowStart = Math.floor((now - 24 * HOUR_MS) / HOUR_MS)
  return snapshot.recentHours.filter(bucket => bucket.hour >= windowStart)
}

/** `provider/model` 形式的键拆成两段；没有斜杠时按未知供应商处理。 */
export function splitModelKey(key: string): { provider: string; model: string } {
  const slash = key.indexOf('/')
  if (slash <= 0) return { provider: 'unknown', model: key }
  return { provider: key.slice(0, slash), model: key.slice(slash + 1) }
}

/**
 * 某范围内按 `provider/model` 聚合的计数，键与 snapshot.byModel 同口径。
 *
 * 模型用量与供应商明细都从这一份结果派生：日级范围走 byModelDay，
 * 「24 小时」走按模型拆分的小时桶，两条路径都保留供应商信息。
 *
 * 「全部」例外：走 snapshot.byModel 而不是逐日累加。原因是对齐口径——
 * 宿主侧 totals.all 在有日级明细时取的是「日级之和」，byModel 与 byDay 由同一次
 * 记账写入，两者天然一致；逐日累加则会受到 retentionDays 裁剪影响而偏小。
 */
export function rangeModelKeyCounters(
  snapshot: MetricsSnapshot,
  range: TimeRange,
  now = Date.now(),
): Map<string, TokenCounters> {
  const totals = new Map<string, TokenCounters>()
  const add = (key: string, counters: Partial<TokenCounters> | undefined): void => {
    if (!counters) return
    const acc = totals.get(key) ?? emptyCounters()
    mergeCounters(acc, counters)
    totals.set(key, acc)
  }

  if (range === '24h') {
    for (const bucket of windowedHours(snapshot, now)) {
      for (const [key, counters] of Object.entries(bucket.byModel)) add(key, counters)
    }
    return totals
  }

  if (range === 'all') {
    for (const [key, counters] of Object.entries(snapshot.byModel ?? {})) add(key, counters)
    return totals
  }

  for (const day of rangeDayKeys(snapshot, range, now)) {
    for (const [key, byDay] of Object.entries(snapshot.byModelDay ?? {})) {
      add(key, byDay[day])
    }
  }
  return totals
}

/** 把 `provider/model` 结果按维度合并成一行一条，并补上缓存命中率。 */
export function groupCounters(
  totals: Map<string, TokenCounters>,
  dimension: 'model' | 'provider',
): Map<string, TokenCountersWithRate> {
  const grouped = new Map<string, TokenCounters>()
  for (const [key, counters] of totals) {
    const name = splitModelKey(key)[dimension]
    const acc = grouped.get(name) ?? emptyCounters()
    mergeCounters(acc, counters)
    grouped.set(name, acc)
  }
  return new Map(
    [...grouped].map(([name, counters]) => [name, { ...counters, cacheHitRate: cacheHitRate(counters) }]),
  )
}

/**
 * 每个 `provider/model` 键在区间内的成本；缺价格的键记为 null。
 * 供应商与模型的成本都由它汇总，避免两处各算一遍价格匹配。
 */
export function costByModelKey(
  snapshot: MetricsSnapshot,
  totals: Map<string, TokenCounters>,
): Map<string, number | null> {
  const cost = new Map<string, number | null>()
  for (const [key, counters] of totals) {
    if ((counters.totalTokens ?? 0) <= 0) continue
    const priceKey = resolveModelKey(snapshot.pricing, splitModelKey(key).model)
    const price = priceKey ? snapshot.pricing[priceKey] : undefined
    cost.set(key, price ? costOf(counters, price) : null)
  }
  return cost
}

/** 滚动 24 小时的成本：用小时桶里的按模型拆分，逐模型计价。 */
export function computeHourlyCost(snapshot: MetricsSnapshot, now = Date.now()): CostSummary {
  let total = 0
  let priced = false
  const missing: string[] = []
  const modelTotals = new Map<string, TokenCounters>()

  for (const bucket of windowedHours(snapshot, now)) {
    for (const [model, counters] of Object.entries(bucket.byModel)) {
      const acc = modelTotals.get(model) ?? emptyCounters()
      mergeCounters(acc, counters)
      modelTotals.set(model, acc)
    }
  }

  for (const [model, counters] of modelTotals) {
    if ((counters.totalTokens ?? 0) <= 0) continue
    const priceKey = resolveModelKey(snapshot.pricing, model)
    const price = priceKey ? snapshot.pricing[priceKey] : undefined
    if (!price) {
      missing.push(model)
      continue
    }
    priced = true
    total += costOf(counters, price)
  }

  return { total, unavailable: !priced, missing }
}

/** 滚动 24 小时的逐小时成本序列，用于成本迷你趋势线。 */
export function hourlyCostSeries(snapshot: MetricsSnapshot, now = Date.now()): number[] {
  const currentHour = Math.floor(now / HOUR_MS)
  const start = currentHour - 23
  const byHour = new Map<number, number>()

  for (const bucket of snapshot.recentHours) {
    if (bucket.hour < start) continue
    let cost = 0
    for (const [model, counters] of Object.entries(bucket.byModel)) {
      const priceKey = resolveModelKey(snapshot.pricing, model)
      const price = priceKey ? snapshot.pricing[priceKey] : undefined
      if (price) cost += costOf(counters, price)
    }
    byHour.set(bucket.hour, cost)
  }

  return Array.from({ length: 24 }, (_, index) => byHour.get(start + index) ?? 0)
}
